using System;using System.IO;using System.Drawing;using System.Xml.Linq;using System.Linq;using ZenQOffice.Core;
class Test{[STAThread]static void Main(){var svg="<svg xmlns='http://www.w3.org/2000/svg' width='100' height='100' viewBox='0 0 100 100'><defs><filter id='blur'><feGaussianBlur stdDeviation='2'/></filter></defs><rect x='40' y='40' width='20' height='20' fill='red' style='filter:url(#blur)'/></svg>";
using var blurred=SvgRasterizer.RenderSvgToBitmap(svg,100,100);using var plain=SvgRasterizer.RenderSvgToBitmap(svg.Replace("style='filter:url(#blur)'",""),100,100);if(blurred.GetPixel(38,50).A==0||plain.GetPixel(38,50).A!=0)throw new Exception("Gaussian blur did not extend a soft edge outside source geometry");if(blurred.GetPixel(10,10).A!=0)throw new Exception("Blur polluted distant transparent pixels");
using var sheet=SvgRasterizer.RenderSvgToBitmap("assets/branding/editable/zenq-icons.svg",1400,340);sheet.Save("output/zenq-calc-style-preview.png");using var calc=SvgRasterizer.RenderSvgToBitmap("assets/branding/editable/calc.svg",280,340);calc.Save("output/zenq-calc-style.png");using(var original=SvgRasterizer.RenderSvgToBitmap("assets/branding/zenq-icons-editable/zenq-icons.svg",1400,340)){
 double error=0;for(int y=0;y<340;y++)for(int x=0;x<280;x++){var a=original.GetPixel(x+280,y);var b=calc.GetPixel(x,y);error+=Math.Abs(a.A-b.A)+Math.Abs(a.R-b.R)+Math.Abs(a.G-b.G)+Math.Abs(a.B-b.B);}error/=280*340*4;Console.WriteLine("User Calc vs extracted SVG pixel difference: "+error.ToString("F4"));if(error>1)throw new Exception("Extracting the user's Calc changed its appearance");
}
Console.WriteLine("PASS: SVG Gaussian blur has a soft alpha falloff; editable icon sheet and user Calc render successfully");}}
